    (recu === undefined ? '' : recu ? ' <span style="color:var(--vert)" title="Reçu par le MiniTiouner">✓✓ reçu</span>' : ' <span class="petit" title="Envoyé, pas encore revu à la réception">✓</span>') + '</div>';
