  const vus = new Set(k ? k.chat.filter(l => l.c === EM.indicatif).map(l => l.seq) : []);
  const fil = EM.chat.map(d => dcBulle(EM.indicatif, d.texte, d.t, true, vus.has(d.seq))).join('');
  const ef = g('e-chat-fil');
