  if (document.activeElement !== g('sstv-continu')) g('sstv-continu').checked = D.continu;
  if (document.activeElement !== g('sstv-nettoyage')) g('sstv-nettoyage').checked = D.nettoyage;
  afcSstv(D.afc);
