    g('o-memoires').innerHTML = O.memoires.map(m => '<button class="' + (Math.abs(m.hz - O.descente) < 500 ? 'ici' : '') + (m.fixe ? '' : ' perso') +
      '" title="' + esc(qFmt(m.hz) + qRegle(m.hz)) + '" onclick="qPost(\'frequence?auto=1&hz=' + m.hz + '\')">' + esc(m.nom) + '</button>').join('');
