  txt('o-crx', mhz(O.cleRx));
  txt('o-cmsg2', !O.cleAtteignable ? 'hors de la plage de la clé : vérifie le LNB' : O.aLaCle && !(OPan && OPan.sdr) ? 'clé arrêtée (onglet SDR)' : '');
