  if (tqZ >= T - B) return { b: B, t: T, plein: true };
  const c = O ? O.descente : (B + T) / 2;
  let f = tqFen && tqFen.z === tqZ ? tqFen : null;
  if (!f || c < f.b + tqZ * 0.2 || c > f.t - tqZ * 0.2) {
    const b = Math.max(B, Math.min(T - tqZ, Math.round((c - tqZ / 2) / 1000) * 1000));
