async function apGarde() {
  if (!apEmisSat && v('ap-sat')) await apSatChange();
  if (!apEmisSat) { txt('ap-f-etat', 'Choisis le satellite.'); return; }
  if (g('ap-aconf').checked) apAconf();
  const de = v('ap-de') ? new Date(v('ap-de')).getTime() : 0, a = v('ap-a') ? new Date(v('ap-a')).getTime() : 0;
  if (!de || !a) { txt('ap-f-etat', 'Donne le début et la fin.'); return; }
  const em = g('ap-emetteur').value, b = id => g(id).checked ? 1 : 0;
  const q = { id: apEdit, nom: v('ap-nom'), catnum: apEmisSat, sat: v('ap-sat'), emetteur: em, freq: em ? '' : v('ap-freq'), modulation: g('ap-modulation').value,
    largeur: v('ap-largeur'), mode: g('ap-mode').value, de: de, a: a, aconfirmer: b('ap-aconf'), el: v('ap-el'), avant: v('ap-avant'), horaire: v('ap-horaire'),
    lien: v('ap-lien'), notes: v('ap-notes'), profil: g('ap-profil').value, source: g('ap-source').value, poste: b('ap-poste'), cposte: b('ap-cposte'),
    rotor: b('ap-rotor'), crotor: b('ap-crotor'), enreg: b('ap-enreg'), sstv: b('ap-sstv'), annonce: b('ap-annonce'), parquer: b('ap-parquer') };
  const j = await post('api/autopilote/campagne?' + Object.keys(q).map(k => k + '=' + enc(q[k])).join('&'));
  if (j && j.ok) { txt('ap-f-etat', 'Campagne enregistrée.'); apEdit = j.campagne.id; txt('ap-f-titre', 'modifier « ' + j.campagne.nom + ' »'); annonce('Campagne SSTV enregistrée'); apVu = ''; apCharge(); }
  else txt('ap-f-etat', (j && j.erreur) || 'Refusé.');
}
async function apActive(id, on) { await post('api/autopilote/active?id=' + enc(id) + '&on=' + (on ? 1 : 0)); apCharge(); }
async function apRetire(id) {
  const c = AP.campagnes.find(x => x.id === id);
  if (!confirm('Retirer la campagne « ' + (c ? c.nom : id) + ' » ? Son historique reste.')) return;
  await post('api/autopilote/retire?id=' + enc(id)); if (apEdit === id) apNouvelle(); apCharge();
}
/** A flyer's proposal into the form, to check before saving. */
async function apPropose(j) {
  if (!j || !j.ok) { txt('ap-imp-etat', (j && j.erreur) || 'Affiche non lue.'); return; }
  const p = j.proposition;
  g('ap-ocr-d').hidden = false; g('ap-ocr').textContent = j.texte || '';
  apNouvelle();
  if (p.nom) g('ap-nom').value = p.nom;
  if (p.catnum) { if (!tous.length) await chargeSatellites(); const s = tous.find(x => x.catnum === p.catnum); g('ap-sat').value = s ? s.nom : p.sat; apEmisSat = s ? p.catnum : 0; }
  if (p.freqHz) g('ap-freq').value = apFreq(p.freqHz);
  await apEmetteurs('');
  if (p.freqHz) { g('ap-emetteur').value = ''; apEmetteurChange(); }
  if (p.mode) g('ap-mode').value = p.mode;
  if (p.de) g('ap-de').value = apLocal(p.de);
  if (p.a) g('ap-a').value = apLocal(p.a);
  g('ap-aconf').checked = !!p.aConfirmer;
  g('ap-horaire').value = p.horaire || ''; g('ap-lien').value = p.lien || '';
  txt('ap-imp-etat', p.trouve.length ? 'Lu : ' + p.trouve.join(', ') + '. Vérifie puis « Enregistrer la campagne ».' : 'Rien d’utile lu : remplir à la main.');
  txt('ap-f-titre', 'proposée par l’affiche');
}
async function apAfficheFichier(inp) {
  const f = inp.files && inp.files[0]; inp.value = ''; if (!f) return;
  if (f.size > 10 * 1024 * 1024) { txt('ap-imp-etat', 'Image trop grande (10 Mo au plus).'); return; }
  txt('ap-imp-etat', 'Lecture de « ' + f.name + ' » par tesseract…');
  try { apPropose(await (await fetch('api/autopilote/affiche', { method: 'POST', body: f })).json()); } catch (x) { txt('ap-imp-etat', 'Lecture impossible.'); }
}
async function apAfficheUrl() {
  const u = v('ap-url'); if (!/^https?:\/\//i.test(u)) { txt('ap-imp-etat', 'Une adresse https://… vers une image.'); return; }
  txt('ap-imp-etat', 'Téléchargement et lecture…');
  try { apPropose(await (await fetch('api/autopilote/affiche?url=' + enc(u), { method: 'POST' })).json()); } catch (x) { txt('ap-imp-etat', 'Lecture impossible.'); }
}
apCharge();
setInterval(apCharge, 3000);
setInterval(ticSon, 1000);

// ------------------------------------------------------------------ Agenda › Activités à venir (online sources)
let AC = null, acVu = '', acNVu = 0;
try { acNVu = +(localStorage.getItem('ac-vu') || 0); } catch (x) {}
const AC_SRC = { ARISS: 'ariss', AMSAT_UK: 'rss', AMSAT_F: 'rss', SATNOGS_M23: 'satnogs', SATNOGS_M24: 'satnogs', AMSAT: 'amsat' };
async function acCharge() {
  try { AC = await (await fetch('api/activites')).json(); } catch (x) { AC = null; }
  if (!AC || !AC.ok) return;
  // The notices not seen yet: a toast each (three at most), the tab's count.
  const nouv = AC.annonces.filter(a => a.n > acNVu);
  nouv.slice(-3).forEach(a => toast((a.sorte === 'emet' ? '📡 ' : a.sorte === 'passage' ? '⏰ ' : '🛰 ') + a.texte));
  if (nouv.length) { acNVu = Math.max.apply(null, nouv.map(a => a.n)); try { localStorage.setItem('ac-vu', acNVu); } catch (x) {} acNonLues += nouv.length; }
  if (ouverte('agenda') && g('ag-p-act') && !g('ag-p-act').hidden) acNonLues = 0;
  g('ac-nb').hidden = !acNonLues; txt('ac-nb', String(acNonLues));
  if (ouverte('agenda')) acDessine();
}
let acNonLues = 0;
const acDate = ms => new Date(ms).toLocaleDateString(undefined, { weekday: 'long', day: 'numeric', month: 'long' });
const acHmUtc = ms => new Date(ms).toISOString().slice(11, 16);
const acHmLoc = ms => { const d = new Date(ms); return String(d.getHours()).padStart(2, '0') + ':' + String(d.getMinutes()).padStart(2, '0'); };
const acJourLoc = ms => new Date(ms).toLocaleDateString(undefined, { day: '2-digit', month: '2-digit' });
/** A period in local time and UTC: « 22/10 17:10 → 26/10 18:45 (15:10 → 17:45 UTC) ». */
function acPeriode(a) {
  if (a.type === 'LRPT') return 'vu le ' + acJourLoc(a.derniere) + ' ' + acHmLoc(a.derniere) + ' (' + acHmUtc(a.derniere) + ' UTC)';
  if (a.precision === 'INCONNUE') return 'annoncé le ' + acJourLoc(a.de) + ', sans horaire : voir le lien';
  if (a.precision === 'JOURS') return 'du ' + acJourLoc(a.de) + ' au ' + acJourLoc(a.a) + ' (horaire à confirmer)';
  const meme = acJourLoc(a.de) === acJourLoc(a.a);
  return acJourLoc(a.de) + ' ' + acHmLoc(a.de) + ' → ' + (meme ? '' : acJourLoc(a.a) + ' ') + acHmLoc(a.a) + ' <span class="petit">(' + acHmUtc(a.de) + ' → ' + acHmUtc(a.a) + ' UTC)</span>';
}
function acReglages() {
  const r = AC.reglages;
  [['ac-actif', r.actif], ['ac-n-nouvelle', r.nouvelle], ['ac-n-passage', r.passage], ['ac-n-emet', r.emet]].forEach(([i, b]) => { if (document.activeElement !== g(i)) g(i).checked = b; });
  if (document.activeElement !== g('ac-avant')) g('ac-avant').value = r.avant;
  txt('ac-elmin', 'Passages d’au moins ' + r.elMin + '° (Réglages › élévation minimale).');
  // One switch per kind of source; its state said quietly (last success, the error).
  const vus = {};
  g('ac-sources').innerHTML = AC.sources.map(s => {
    const k = AC_SRC[s.id], premier = !vus[k]; vus[k] = 1;
    const etat = !s.actif ? 'coupée' : s.erreur ? '<span class="err" title="' + escA(s.erreur) + '">⚠ ' + esc(s.erreur.slice(0, 40)) + '</span>' + (s.succes ? ' · lu le ' + jourHeure(s.succes) : '') :
      s.succes ? 'lu le ' + jourHeure(s.succes) : s.id === 'AMSAT' ? 'seulement pendant une SSTV/SSDV annoncée' : 'pas encore lu';
    return '<span>' + (premier ? '<input type="checkbox" title="Cette source" ' + (r[k] ? 'checked' : '') + (r.actif ? '' : ' disabled') + ' onchange="acReglage(\'' + k + '\', this.checked)">' : '') + '</span>' +
      '<span><a href="' + escA(s.lien) + '" target="_blank" rel="noopener noreferrer">' + esc(s.nom) + '</a> <span class="petit">' + etat + '</span></span>';
  }).join('');
}
function acDessine() {
  if (!AC || !AC.ok) return;
  acReglages();
  g('ac-annonces').innerHTML = AC.annonces.slice().reverse().slice(0, 10).map(a => jourHeure(a.quand) + ' — ' + esc(a.texte)).join('<br>') || 'aucune depuis le démarrage';
  const cle = JSON.stringify([AC.activites, AC.reglages.actif, utc()]);
  if (cle === acVu) return;
  acVu = cle;
  const l = AC.activites;
  txt('ac-resume', !AC.reglages.actif ? 'coupé' : l.length + ' activité' + (l.length > 1 ? 's' : ''));
  if (!AC.reglages.actif) { g('ac-liste').innerHTML = '<div class="petit">Coupé : aucune source n’est demandée.</div>'; return; }
  // Seen recently (METEOR) first, then by day.
  const vus = l.filter(a => a.type === 'LRPT'), annonces = l.filter(a => a.type !== 'LRPT');
  let h = '', jour = '';
  if (vus.length) h += '<div class="ac-jour">Vu récemment</div>' + vus.map(acCarte).join('');
  annonces.forEach(a => { const j = acDate(Math.max(a.de, Math.min(AC.maintenant, a.a))); if (j !== jour) { jour = j; h += '<div class="ac-jour">' + esc(j) + '</div>'; } h += acCarte(a); });
  g('ac-liste').innerHTML = h || '<div class="petit">Rien d’annoncé pour l’instant' + (AC.sources.some(s => s.succes) ? '.' : ' (les sources n’ont pas encore été lues).') + '</div>';
}
function acCarte(a) {
  const enCours = a.type !== 'LRPT' && a.de <= AC.maintenant && AC.maintenant <= a.a;
  const src = a.sources.map(s => s.lien ? '<a href="' + escA(s.lien) + '" target="_blank" rel="noopener noreferrer">' + esc(s.nom) + '</a>' : esc(s.nom)).join(', ');
  const pass = a.passages.length ? '<div class="ac-pass">' + (a.type === 'LRPT' ? 'Passages (24 h) :' : 'Tes passages :') + a.passages.map(p => ' <span title="' + acHmUtc(p.aos) + ' UTC">' + acJourLoc(p.aos) + ' ' + acHmLoc(p.aos) + ' · ' + p.el + '°</span>').join('') + '</div>' :
    a.catnum ? '<div class="petit">Aucun passage assez haut ici' + (a.type === 'CONTACT' ? ' (contact entendu ailleurs)' : '') + '.</div>' : '';
  return '<div class="ac-act' + (enCours ? ' encours' : '') + '"><div class="ac-t"><b>' + esc(a.sat || '?') + '</b><span class="pastille ac-' + a.type + '">' + esc(a.libelle) + '</span>' +
    '<span class="pastille' + (a.confiance === 'CONFIRME' ? ' ac-c-CONFIRME' : ' off') + '">' + esc(a.confianceLibelle) + (a.ecoutes && a.type !== 'LRPT' ? ' · ' + a.ecoutes : '') + '</span>' + (enCours ? '<span class="pastille ap-st-EN_COURS">en cours</span>' : '') +
    '<span class="act">' + (a.campagne ? '<button onclick="acPrepare(\'' + escA(a.id).replace(/'/g, '') + '\')" title="Ouvrir Agenda › SSTV avec la campagne remplie, à vérifier puis enregistrer">Préparer la campagne SSTV</button>' : '') + '</span></div>' +
    '<div>' + esc(a.titre) + '</div>' +
    '<div class="petit">' + acPeriode(a) + '</div>' +
    '<div class="petit">' + (a.freqHz ? '<span class="ac-f">' + apFreq(a.freqHz) + ' MHz</span> ' + esc(a.modulation === 'LRPT' ? '' : a.modulation) : 'fréquence non dite') + (a.mode && a.mode !== 'LRPT' ? ' · ' + esc(a.mode) : '') + (a.horaire ? ' · ' + esc(a.horaire) : '') + '</div>' +
    (a.details ? '<div class="petit">' + esc(a.details) + '</div>' : '') + pass +
    '<div class="petit">Sources : ' + src + a.liens.filter(x => !a.sources.some(s => s.lien === x)).slice(0, 2).map(x => ' · <a href="' + escA(x) + '" target="_blank" rel="noopener noreferrer">lien ↗</a>').join('') + '</div></div>';
}
async function acReglage(k, on) { await post('api/activites/reglage?k=' + k + '&on=' + (on ? 1 : 0)); acVu = ''; acCharge(); }
async function acActualise() { await post('api/activites/rafraichit'); annonce('Sources demandées'); setTimeout(acCharge, 8000); }
/** « Préparer la campagne SSTV »: Agenda › SSTV's form filled, to check before saving (nothing saved here). */
async function acPrepare(id) {
  let j = null;
  try { j = await (await fetch('api/activites/campagne?id=' + enc(id))).json(); } catch (x) {}
  if (!j || !j.ok) { alert((j && j.erreur) || 'Activité introuvable.'); return; }
  apOuvre();
  await apPropose(j);
  g('ap-ocr-d').hidden = true;
  if (j.proposition.notes) g('ap-notes').value = j.proposition.notes;
  txt('ap-f-titre', 'proposée par « Activités à venir »');
  txt('ap-imp-etat', 'Rempli d’après l’activité : vérifie puis « Enregistrer la campagne ».');
  g('ap-form').scrollIntoView({ block: 'nearest' });
}
acCharge();
setInterval(acCharge, 60000);

// ------------------------------------------------------------------ Montage: the station's chain, drawn and lit
// Display and setup only: nothing here starts a transmission, opens a port or touches the LNB supply.
var MT = { cat: null, d: null, cle: '', simple: false, edition: false, sel: null, essai: '', telephone: false, pop: null, popCle: '' };
try { MT.simple = localStorage.getItem('mt-simple') === '1'; } catch (x) {}
try { const q = new URLSearchParams(location.search).get('essai'); if (['rx', 'tx', 'datv-pluto', 'sstv-carte', 'sstv-reseau'].includes(q)) MT.essai = q; } catch (x) {}
try { MT.fonction = localStorage.getItem('mt-fonction') || ''; } catch (x) { MT.fonction = ''; }
const MT_CABLES = {
  COAX_N: 'N', COAX_SMA: 'SMA', COAX_F: 'F', COAX_BNC: 'BNC', COAX_PL: 'PL', DIRECT: '', USB: 'USB', ETHERNET: 'Réseau', WIFI: 'Wi-Fi',
  AUDIO: 'Audio', CAT: 'CAT', PTT: 'PTT', ROTOR: 'Rotor', REFERENCE: 'Réf.', ALIM: 'DC', GPS: 'GPS', INTERNET: 'Internet'
};
const MT_ETATS = { rx: 'reçoit', tx: 'émet', rxtx: 'reçoit et émet', relie: 'connecté', repos: 'au repos' };
const mtEsc = x => String(x == null ? '' : x).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/"/g, '&quot;');
const mtMhz = m => m >= 1000 ? m.toFixed(3).replace('.', ',') : m.toFixed(3).replace('.', ',');
function mtBande(mhz) {
  if (!mhz) return '';
  if (mhz >= 10000) return '10 GHz';
  if (mhz >= 2000) return '2,4 GHz';
  if (mhz >= 1200) return '23 cm';
  if (mhz >= 700) return mhz + ' MHz FI';
  if (mhz >= 400) return '70 cm';
  if (mhz >= 140) return '2 m';
  return mhz + ' MHz';
}
const mtModele = id => MT.cat && MT.cat.par[id];
const mtElem = (c, id) => c.elements.find(e => e.id === id);
const mtNom = e => e.nom || (mtModele(e.m) || {}).court || (mtModele(e.m) || {}).nom || e.m;
/** An element's ports: its own when its options change them (sent with the chain), else the catalogue's. */
const mtPortsEl = el => { if (!el) return []; if (el._p) return el._p; const m = mtModele(el.m); return m ? m.ports : []; };
function mtPort(c, bout) {
  const [e, p] = String(bout).split('.'); const el = mtElem(c, e);
  return el ? (mtPortsEl(el).find(x => x.id === p) || null) : null;
}
function mtAttachePorts(d) { const ps = (d && d.ports) || {}; ((d && d.chaine && d.chaine.elements) || []).forEach(e => { if (ps[e.id]) e._p = ps[e.id]; }); }
const mtFam = id => ((MT.cat && MT.cat.cables.find(x => x.id === id)) || {}).famille || 'COAX';
/** The band a radio cable carries: the output's when one end is an output, else the higher. */
function mtBandeCable(a, b) { const s = [a, b].filter(p => p && p.sens === 'SORTIE' && p.mhz); return s.length === 1 ? s[0].mhz : Math.max((a && a.mhz) || 0, (b && b.mhz) || 0); }
async function mtCatalogue() {
  if (MT.cat) return MT.cat;
  try {
    const j = await (await fetch('api/montage/catalogue')).json();
    j.par = {}; j.modeles.forEach(m => j.par[m.id] = m);
    MT.cat = j;
  } catch (x) {}
  return MT.cat;
}

// ---- the drawings: SatMe's own, a stylised front panel (no maker's picture, no mark)
const MT_D = (() => {
  const R = (x, y, w, h, r, f, s, sw) => '<rect x="' + x + '" y="' + y + '" width="' + w + '" height="' + h + '" rx="' + (r || 0) + '" fill="' + f + '"' + (s ? ' stroke="' + s + '" stroke-width="' + (sw || 1) + '"' : '') + '/>';
  const C = (x, y, r, f, s, sw) => '<circle cx="' + x + '" cy="' + y + '" r="' + r + '" fill="' + f + '"' + (s ? ' stroke="' + s + '" stroke-width="' + (sw || 1) + '"' : '') + '/>';
  const P = (d, f, s, sw, x) => '<path d="' + d + '" fill="' + (f || 'none') + '"' + (s ? ' stroke="' + s + '" stroke-width="' + (sw || 1) + '"' : '') + (x || '') + '/>';
  const T = (x, y, t, sz, f, a) => '<text x="' + x + '" y="' + y + '" font-size="' + sz + '" fill="' + (f || '#9AA7B4') + '" text-anchor="' + (a || 'middle') + '" font-family="ui-monospace,monospace">' + t + '</text>';
  const sma = (x, y, v) => v ? R(x - 3, y, 6, 7, 1, '#C9A54A', '#8A6E2A', .6) : R(x, y - 3, 7, 6, 1, '#C9A54A', '#8A6E2A', .6);
  const fco = (x, y) => R(x, y - 4, 8, 8, 1.5, '#B9C2CC', '#6E7883', .6) + C(x + 4, y, 1.4, '#3A434D');
  const usbC = (x, y) => R(x, y - 3, 5, 6, 1.5, '#1A1F24', '#7D8893', .7);
  const led = (x, y, c) => C(x, y, 1.8, c) + C(x, y, 3.2, c, null, 0).replace('fill="' + c + '"', 'fill="' + c + '" opacity=".25"');
  const knob = (x, y, r) => C(x, y, r, 'url(#P-bouton)', '#0B0F13', 1) + C(x, y, r * .72, 'none', 'rgba(255,255,255,.08)', 1) + C(x + r * .45, y - r * .35, r * .12, '#0B0F13');
  const ecran = (x, y, w, h, teinte) => R(x, y, w, h, 2, teinte || 'url(#P-ecran)', '#05080B', 1.2) +
    P('M' + (x + 3) + ' ' + (y + h * .78) + ' l' + (w * .12) + ' -' + (h * .18) + ' l' + (w * .1) + ' ' + (h * .1) + ' l' + (w * .1) + ' -' + (h * .34) + ' l' + (w * .1) + ' ' + (h * .3) + ' l' + (w * .15) + ' -' + (h * .12) + ' l' + (w * .1) + ' ' + (h * .08) + ' l' + (w * .2) + ' -' + (h * .1), 'none', 'rgba(63,224,200,.85)', 1) +
    R(x + 3, y + 3, w * .45, h * .2, 1, 'rgba(232,240,247,.55)');
  const corps = (w, h, f) => R(1, 1, w - 2, h - 2, 5, f || 'url(#P-noir)', '#0B0F13', 1.2) + R(3, 3, w - 6, 3, 1.5, 'rgba(255,255,255,.06)');
  const poste = (w, h, o) => {
    let s = corps(w, h) + R(4, h - 4, 10, 3, 1, '#0B0F13') + R(w - 14, h - 4, 10, 3, 1, '#0B0F13');
    const ex = w * o.ex, ey = h * .14, ew = w * o.ew, eh = h * o.eh;
    s += ecran(ex, ey, ew, eh, o.teinte);
    s += knob(w * o.kx, h * .54, h * o.kr);
    for (let i = 0; i < o.bt; i++) s += R(ex + i * (ew / o.bt) + 1, ey + eh + 5, ew / o.bt - 3, 4, 1, '#3A4450');
    (o.petits || []).forEach(k => { s += C(w * k[0], h * k[1], h * k[2], 'url(#P-bouton)', '#0B0F13', .8); });
    s += R(5, h * .2, 7, 7, 3.5, '#3A4450') + led(w * o.kx, h * .14, '#5BD68A');
    return s;
  };
  return {
    parabole: (w, h) => {
      const cx = w * .46, cy = h * .44;
      return R(w * .55, h * .6, 6, h * .4, 1, '#59636E') + R(w * .42, h - 5, w * .34, 5, 2, '#3A4450') +
        '<g transform="rotate(-24 ' + cx + ' ' + cy + ')">' + '<ellipse cx="' + cx + '" cy="' + cy + '" rx="' + (w * .15) + '" ry="' + (h * .42) + '" fill="url(#P-metal)" stroke="#5D6873" stroke-width="1.2"/>' +
        '<ellipse cx="' + (cx + 3) + '" cy="' + cy + '" rx="' + (w * .1) + '" ry="' + (h * .36) + '" fill="rgba(11,15,19,.18)"/></g>' +
        P('M' + (w * .5) + ' ' + (h * .8) + ' L' + (w * .14) + ' ' + (h * .6), 'none', '#7D8893', 2.4) +
        R(w * .04, h * .5, 13, 16, 2, '#E3E8ED', '#7D8893', .8) + R(w * .02, h * .53, 4, 10, 1, '#FFB454') +
        '<ellipse cx="' + (w * .17) + '" cy="' + (h * .58) + '" rx="7" ry="5" fill="#C9D2DB" stroke="#7D8893" stroke-width=".8"/>';
    },
    yagi: (w, h) => {
      const y = h * .42, n = 9; let s = R(w / 2 - 2, y, 4, h - y, 1, '#59636E') + R(w * .06, y - 1.5, w * .88, 3, 1.5, '#9AA7B4');
      for (let i = 0; i < n; i++) { const x = w * .1 + i * w * .8 / (n - 1), l = h * (.86 - i * .045); s += R(x - 1, y - l / 2, 2.2, l, 1, i === 1 ? '#E8F0F7' : '#C9D2DB'); }
      return s + R(w * .1 + w * .8 / (n - 1) - 5, y + 3, 10, 6, 1, '#1A1F24', '#7D8893', .6);
