  else if (fam === 'DIRECT') s += '<path class="mt-direct" d="' + d + '"/>';
  else s += '<path class="mt-fil" d="' + d + '"/>';
  s += '<path class="mt-flux" d="' + d + '"/>';
  if (fam === 'WIFI' && t.et) {
    const [x, y] = t.et;
