  }
  s += '<circle class="mt-port" cx="' + t.de[0] + '" cy="' + t.de[1] + '" r="3"/><circle class="mt-port" cx="' + t.vers[0] + '" cy="' + t.vers[1] + '" r="3"/>';
  s += '<path class="mt-hit" d="' + d + '"/>';
