function nsOff(n) { return !!(NS && NS[n] === false); }
const ESPACES_WS = [...document.querySelectorAll('#onglets .ws')].map(w => w.dataset.ws);
try { wsDernier = JSON.parse(localStorage.getItem('ws-dernier') || '{}') || {}; } catch (x) {}
